def solve(arr):
    """Flatten a nested list of integers.
    Args:
        arr (list): List possibly containing integers or other nested lists.
    Returns:
        list: Flat list of integers preserving order.
    """
    result = []
    stack = [iter(arr)]
    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue
        if isinstance(item, list):
            stack.append(iter(item))
        else:
            result.append(item)
    return result

