def solve(n):
    """Return the count of prime numbers strictly less than n.
    Uses the Sieve of Eratosthenes for n up to reasonable limits.
    """
    if n <= 2:
        return 0
    limit = n - 1
    sieve = bytearray(b'\x01') * (limit + 1)  # assume all prime initially
    sieve[0:2] = b'\x00\x00'  # 0 and 1 not prime
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if sieve[p]:
            step = p
            start = p * p
            sieve[start:limit+1:step] = b'\x00' * ((limit - start) // step + 1)
    return sum(sieve)

