def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Handles None or non-iterable inputs by treating them as empty.
    Implements patience sorting using bisect for O(n log n).
    """
    if not nums:
        return 0
    import bisect
    tails = []
    for x in nums:
        # find first element >= x
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

