def solve(grid):
    """Count number of islands (connected components of 1s) in a grid.
    grid: list of list of ints (0 or 1). Adjacent 4-directionally.
    Empty grid returns 0.
    """
    if not grid:
        return 0
    n = len(grid)
    m = len(grid[0]) if n else 0
    visited = [[False]*m for _ in range(n)]
    def bfs(sr, sc):
        from collections import deque
        dq = deque()
        dq.append((sr, sc))
        visited[sr][sc] = True
        while dq:
            r, c = dq.popleft()
            for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr, nc = r+dr, c+dc
                if 0 <= nr < n and 0 <= nc < m and not visited[nr][nc] and grid[nr][nc]==1:
                    visited[nr][nc] = True
                    dq.append((nr, nc))
    count = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1 and not visited[i][j]:
                bfs(i, j)
                count += 1
    return count

