def solve(words):
    """Group anagrams together. Sort each group alphabetically, then sort the
    groups by their first element, and return the list of groups."""
    groups = {}
    for w in words:
        key = ''.join(sorted(w))
        groups.setdefault(key, []).append(w)
    result = [sorted(g) for g in groups.values()]
    result.sort(key=lambda g: g[0])
    return result

